import nltk
from string import punctuation
import pandas as pd

def task_func(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    counts = {}
    order = []

    for word in text.split():
        if word.startswith("$") and any(ch not in punctuation for ch in word):
            if word not in counts:
                counts[word] = 0
                order.append(word)
            counts[word] += 1

    return pd.DataFrame(
        {"Word": order, "Frequency": [counts[word] for word in order]}
    )
